#include <Common/EngineEnvironment.h>
#include <Mahjong/Table/TileAtlas.h>
#include <gtest/gtest.h>

/**
 * The tile art: `assets/tiles/tiles.png` and `config/TextureLibrary.xml` are generated by `tools/make_tiles.py` and read here from the
 * source tree (a game's content is not mounted in the test environment). The PNG is checked by its header (zlib is not linked into the
 * tests; the pixels are checked by `python3 tools/make_tiles.py --check`), the XML by its `Tile_` sprites against `Table/TileAtlas.h`.
 */
namespace BECore::Mahjong::Tests {

    using namespace BECore::Tests;

    namespace {

        constexpr size_t kPngSignatureSize = 8;
        constexpr size_t kIhdrDataOffset = kPngSignatureSize + 8;  // after the signature, the chunk length and the chunk type
        constexpr size_t kIhdrSize = 13;
        constexpr size_t kIhdrTypeOffset = kPngSignatureSize + 4;  // the chunk type follows the 4 bytes of the chunk length
        constexpr size_t kIhdrHeightOffset = 4;                    // within the chunk data: width (4), height (4), depth, colour type, ...
        constexpr size_t kIhdrDepthOffset = 8;
        constexpr size_t kIhdrColorTypeOffset = 9;
        constexpr size_t kIhdrInterlaceOffset = 12;
        constexpr uint8_t kBitDepth = 8;
        constexpr uint8_t kColorTypeRgba = 6;
        constexpr uint8_t kNoInterlace = 0;
        constexpr unsigned char kPngSignature[kPngSignatureSize] = {0x89, 'P', 'N', 'G', '\r', '\n', 0x1A, '\n'};

        std::filesystem::path GameRoot() {
            return std::filesystem::path(__FILE__).parent_path().parent_path();
        }

        uint32_t ReadBigEndian(const std::vector<unsigned char>& bytes, size_t offset) {
            return (static_cast<uint32_t>(bytes[offset]) << 24) | (static_cast<uint32_t>(bytes[offset + 1]) << 16) | (static_cast<uint32_t>(bytes[offset + 2]) << 8) |
                   static_cast<uint32_t>(bytes[offset + 3]);
        }

        constexpr eastl::string_view kTileSpritePrefix = "Tile_";

        struct Sprite {
            eastl::string name;
            eastl::string texturePath;
            Rect rect;
        };

        bool Overlap(const Rect& a, const Rect& b) {
            return a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
        }

    }  // namespace

    class TileSpritesTest : public ::testing::Test {
    protected:
        static void SetUpTestSuite() {
            EngineEnvironment::EnsureCoreServices();
        }

        void SetUp() override {
            const std::filesystem::path xmlPath = GameRoot() / "config" / "TextureLibrary.xml";
            const XmlConfig config = XmlConfig::Create();
            ASSERT_TRUE(config.LoadFromFile(xmlPath)) << xmlPath.string();
            // The shape TextureLibrary::Initialize reads: the document element has the child "sprites", whatever its own name
            const XmlNode sprites = config.GetRoot().GetChild("sprites");
            ASSERT_TRUE(static_cast<bool>(sprites));
            for (const XmlNode node : sprites.Children()) {
                if (node.Name() != eastl::string_view("sprite")) {
                    continue;
                }
                Sprite sprite;
                sprite.name = eastl::string(node.GetAttribute("name").value_or(""));
                if (sprite.name.compare(0, kTileSpritePrefix.size(), kTileSpritePrefix.data()) != 0) {
                    continue;  // the library also holds the icons (IconSpritesTest)
                }
                sprite.texturePath = eastl::string(node.GetAttribute("texturePath").value_or(""));
                const XmlNode source = node.GetChild("srcRect");
                ASSERT_TRUE(static_cast<bool>(source)) << sprite.name.c_str();
                sprite.rect = Rect(source.ParseAttribute<float>("x").value_or(-1.0f), source.ParseAttribute<float>("y").value_or(-1.0f), source.ParseAttribute<float>("w").value_or(-1.0f),
                                   source.ParseAttribute<float>("h").value_or(-1.0f));
                _sprites.push_back(sprite);
            }
        }

        eastl::vector<Sprite> _sprites;
    };

    TEST_F(TileSpritesTest, ThePngIsAnRgbaPictureOfTheAtlasSize) {
        const std::filesystem::path pngPath = GameRoot() / kAtlasPath;
        std::ifstream file(pngPath, std::ios::binary);
        ASSERT_TRUE(file.is_open()) << pngPath.string();
        std::vector<unsigned char> head(kIhdrDataOffset + kIhdrSize);
        file.read(reinterpret_cast<char*>(head.data()), static_cast<std::streamsize>(head.size()));
        ASSERT_EQ(static_cast<size_t>(file.gcount()), head.size());
        EXPECT_TRUE(std::equal(std::begin(kPngSignature), std::end(kPngSignature), head.begin()));
        EXPECT_EQ(std::string(head.begin() + kIhdrTypeOffset, head.begin() + kIhdrDataOffset), "IHDR");
        EXPECT_EQ(ReadBigEndian(head, kIhdrDataOffset), static_cast<uint32_t>(kAtlasWidth));
        EXPECT_EQ(ReadBigEndian(head, kIhdrDataOffset + kIhdrHeightOffset), static_cast<uint32_t>(kAtlasHeight));
        EXPECT_EQ(head[kIhdrDataOffset + kIhdrDepthOffset], kBitDepth);
        EXPECT_EQ(head[kIhdrDataOffset + kIhdrColorTypeOffset], kColorTypeRgba);
        EXPECT_EQ(head[kIhdrDataOffset + kIhdrInterlaceOffset], kNoInterlace);
    }

    TEST_F(TileSpritesTest, TheLibraryHoldsOneSpritePerTileAndTheBack) {
        ASSERT_EQ(_sprites.size(), static_cast<size_t>(kDrawnCells));
        for (const Sprite& sprite : _sprites) {
            EXPECT_EQ(sprite.texturePath, eastl::string(kAtlasPath)) << sprite.name.c_str();
        }
    }

    TEST_F(TileSpritesTest, EverySpriteIsWhereTheArithmeticSaysAndInTheSameOrderAsTheIds) {
        ASSERT_EQ(_sprites.size(), static_cast<size_t>(kDrawnCells));
        for (uint8_t id = 0; id < kTileIdCount; ++id) {
            const Tile tile{id};
            const Sprite& sprite = _sprites[id];
            EXPECT_EQ(sprite.name, SpriteName(tile)) << static_cast<int>(id);
            const Rect expected = SourceRect(tile);
            EXPECT_EQ(sprite.rect.x, expected.x) << sprite.name.c_str();
            EXPECT_EQ(sprite.rect.y, expected.y) << sprite.name.c_str();
            EXPECT_EQ(sprite.rect.w, expected.w) << sprite.name.c_str();
            EXPECT_EQ(sprite.rect.h, expected.h) << sprite.name.c_str();
        }
        const Sprite& back = _sprites[kBackCell];
        const Rect expectedBack = BackRect();
        EXPECT_EQ(back.name, eastl::string(kBackSpriteName));
        EXPECT_EQ(back.rect.x, expectedBack.x);
        EXPECT_EQ(back.rect.y, expectedBack.y);
        EXPECT_EQ(back.rect.w, expectedBack.w);
        EXPECT_EQ(back.rect.h, expectedBack.h);
    }

    TEST_F(TileSpritesTest, TheStackSpriteIsTheSquareOfTheCellAfterTheBack) {
        ASSERT_EQ(_sprites.size(), static_cast<size_t>(kDrawnCells));
        EXPECT_EQ(kStackCell, kBackCell + 1);
        const Sprite& stack = _sprites[kStackCell];
        const Rect expected = StackRect();
        EXPECT_EQ(stack.name, eastl::string(kStackSpriteName));
        EXPECT_EQ(stack.rect.x, expected.x);
        EXPECT_EQ(stack.rect.y, expected.y);
        EXPECT_EQ(stack.rect.w, expected.w);
        EXPECT_EQ(stack.rect.h, expected.h);
        EXPECT_EQ(expected.x, CellRect(kStackCell).x);
        EXPECT_EQ(expected.y, CellRect(kStackCell).y);
        EXPECT_EQ(expected.w, static_cast<float>(kStackSize));
        EXPECT_EQ(expected.h, static_cast<float>(kStackSize));
    }

    TEST_F(TileSpritesTest, SpriteNamesAreDistinctAndFollowTheNotation) {
        EXPECT_EQ(SpriteName(*TryParse("5p")), eastl::string("Tile_5p"));
        EXPECT_EQ(SpriteName(*TryParse("Ew")), eastl::string("Tile_Ew"));
        EXPECT_EQ(SpriteName(*TryParse("Rd")), eastl::string("Tile_Rd"));
        EXPECT_EQ(SpriteName(*TryParse("F1")), eastl::string("Tile_F1"));
        EXPECT_EQ(SpriteName(*TryParse("T4")), eastl::string("Tile_T4"));
        EXPECT_EQ(SpriteName(Tile{}), eastl::string(kBackSpriteName));
        for (size_t first = 0; first < _sprites.size(); ++first) {
            for (size_t second = first + 1; second < _sprites.size(); ++second) {
                EXPECT_NE(_sprites[first].name, _sprites[second].name);
            }
        }
    }

    TEST_F(TileSpritesTest, EveryRectLiesInsideTheImageAndNoTwoOverlap) {
        for (size_t first = 0; first < _sprites.size(); ++first) {
            const Rect& rect = _sprites[first].rect;
            EXPECT_GE(rect.x, 0.0f) << _sprites[first].name.c_str();
            EXPECT_GE(rect.y, 0.0f) << _sprites[first].name.c_str();
            EXPECT_GT(rect.w, 0.0f) << _sprites[first].name.c_str();
            EXPECT_GT(rect.h, 0.0f) << _sprites[first].name.c_str();
            EXPECT_LE(rect.x + rect.w, static_cast<float>(kAtlasWidth)) << _sprites[first].name.c_str();
            EXPECT_LE(rect.y + rect.h, static_cast<float>(kAtlasHeight)) << _sprites[first].name.c_str();
            for (size_t second = first + 1; second < _sprites.size(); ++second) {
                EXPECT_FALSE(Overlap(rect, _sprites[second].rect)) << _sprites[first].name.c_str() << " and " << _sprites[second].name.c_str();
            }
        }
    }

    TEST(TileAtlasTest, TheGridHoldsEveryCellAndTheAtlasSizeIsTheGrid) {
        EXPECT_EQ(kAtlasWidth, kAtlasColumns * kCellWidth);
        EXPECT_EQ(kAtlasHeight, kAtlasRows * kCellHeight);
        EXPECT_EQ(kDrawnCells, kTileIdCount + 2);
        EXPECT_EQ(SourceRect(Tile{0}).x, 0.0f);
        EXPECT_EQ(SourceRect(Tile{0}).y, 0.0f);
        // The first cell of the second row and the last drawn one
        EXPECT_EQ(CellRect(kAtlasColumns).x, 0.0f);
        EXPECT_EQ(CellRect(kAtlasColumns).y, static_cast<float>(kCellHeight));
        EXPECT_EQ(BackRect().x, static_cast<float>(kBackCell % kAtlasColumns * kCellWidth));
        EXPECT_EQ(BackRect().y, static_cast<float>(kBackCell / kAtlasColumns * kCellHeight));
        // An invalid tile has no face: it is drawn as the back
        EXPECT_EQ(SourceRect(Tile{}).x, BackRect().x);
        EXPECT_EQ(SourceRect(Tile{}).y, BackRect().y);
    }

}  // namespace BECore::Mahjong::Tests
